const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({model:'ACT',datasets:[{id:'DS-001',name:'桌面物体抓取 · 第一批',task:'桌面抓取',episodes:128,quality:98.2,date:'2026-11-06',version:'v1.2'},{id:'DS-002',name:'双臂协同搬运 · 示教集',task:'双臂搬运',episodes:86,quality:96.5,date:'2026-11-05',version:'v1.0'},{id:'DS-003',name:'灵巧手开合 · 标定样本',task:'灵巧手控制',episodes:42,quality:99.1,date:'2026-11-04',version:'v1.0'}],jobs:[{id:'TR-001',name:'桌面抓取 / ACT 基线',model:'ACT',dataset:'DS-001',progress:100,status:'已完成',loss:0.024}],deployments:[],joints:[0,0,0,0],logs:[]});
let state;try{state=JSON.parse(localStorage.getItem('embodied-demo-v1'))||initial()}catch{state=initial()}let page='',capture={running:false,seconds:0,task:'桌面抓取'},filter='全部',toastTimeout;
const save=()=>localStorage.setItem('embodied-demo-v1',JSON.stringify(state));const toast=t=>{clearTimeout(toastTimeout);$('#toast').textContent=t;$('#toast').style.display='block';toastTimeout=setTimeout(()=>$('#toast').style.display='none',3200)};const closeModal=()=>$('#dialog').close();
const icons=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M8 3h8v5H8z M5 10h14v9H5z M2 11v6 M22 11v6 M8 19v3 M16 19v3','M4 5h16v14H4z M9 9l7 3-7 3z','M3 6c0-4 18-4 18 0s-18 4-18 0 M3 6v12c0 4 18 4 18 0V6 M3 12c0 4 18 4 18 0','M12 2l9 5v10l-9 5-9-5V7z M3 7l9 5 9-5 M12 12v10','M4 20V10 M10 20V4 M16 20v-8 M22 20V2','M12 16V3 M7 8l5-5 5 5 M3 15v6h18v-6','M8 3h8v5H8z M2 16h7v5H2z M15 16h7v5h-7z M12 8v4 M5 16v-4h14v4'];
const pages=[['overview','项目总览'],['devices','设备调试'],['capture','遥操作数采'],['datasets','数据管理'],['models','模型中心'],['training','训练实验'],['deploy','部署运行'],['architecture','整体架构']];
$('#nav').innerHTML=pages.map(([id,name],i)=>(i===1?'<div class="nav-label">DEVELOPMENT</div>':i===7?'<div class="nav-label">SYSTEM</div>':'')+`<a href="#${id}" data-page="${id}"><svg viewBox="0 0 24 24"><path d="${icons[i]}"/></svg>${name}</a>`).join('');
const badge=(t,c='')=>`<span class="badge ${c}">${t}</span>`;
const head=(title,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">EMBODIED RESEARCH WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
function robot(){return `<svg viewBox="0 0 500 280" role="img" aria-label="G1 人形机器人示意图"><defs><linearGradient id="metal" x2="1" y2="1"><stop stop-color="#e3ede8"/><stop offset="1" stop-color="#8caaa5"/></linearGradient><pattern id="grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M28 0H0V28" fill="none" stroke="#77a89b" stroke-width=".4"/></pattern></defs><rect width="500" height="280" fill="url(#grid)" opacity=".2"/><ellipse cx="254" cy="253" rx="111" ry="17" fill="#6fae9722"/><g stroke="#628e83" stroke-width="1.5"><path d="M156 245L250 222 347 245 253 269Z" fill="none"/><path d="M156 245v-7 M347 245v-7"/></g><g fill="url(#metal)" stroke="#54776f" stroke-width="2"><rect x="229" y="29" width="43" height="40" rx="15"/><rect x="227" y="44" width="46" height="13" rx="6" fill="#193731"/><rect x="243" y="70" width="17" height="11" rx="3"/><path d="M219 82Q250 74 282 82L276 134 226 134Z"/><path d="M228 140h47l-5 29h-37Z"/><rect x="194" y="83" width="22" height="43" rx="10" transform="rotate(15 205 90)"/><rect x="184" y="129" width="19" height="42" rx="8" transform="rotate(-12 190 130)"/><rect x="286" y="83" width="22" height="43" rx="10" transform="rotate(-15 296 90)"/><rect x="300" y="128" width="19" height="42" rx="8" transform="rotate(12 310 130)"/><rect x="225" y="171" width="21" height="37" rx="8"/><rect x="258" y="171" width="21" height="37" rx="8"/><rect x="224" y="213" width="20" height="30" rx="7"/><rect x="260" y="213" width="20" height="30" rx="7"/><path d="M222 240h22v11h-31q-4-9 9-11Z"/><path d="M260 240h22q13 2 9 11h-31Z"/></g><g fill="#355d50"><circle cx="235" cy="210" r="7"/><circle cx="269" cy="210" r="7"/><rect x="237" y="96" width="29" height="24" rx="5"/></g><g stroke="#b5dbc6" stroke-width="4" stroke-linecap="round"><path d="M193 172v15m6-15v16m6-16v13m-18-13v12m8-14-12 4 M305 172v15m6-15v16m6-16v13m-18-13v12m10-14 14 4"/></g><g stroke="#8acdb0" stroke-width=".8" fill="none"><path d="M318 181h55l15-15h45 M264 109h94l13-15h58"/><circle cx="318" cy="181" r="3"/><circle cx="264" cy="109" r="3"/></g><g font-family="monospace" font-size="9" fill="#add5c4"><text x="367" y="86">UNITREE G1</text><text x="375" y="158">INSPIRE HAND</text><text x="37" y="226">SIMULATION</text><text x="37" y="241" fill="#6e9d8f">NO HARDWARE LINK</text></g></svg>`}
function metrics(){return `<div class="metrics">${[['设备连接','2','台','G1 + 因时灵巧手 · 模拟在线'],['示教数据',state.datasets.reduce((s,d)=>s+d.episodes,0),'条',`${state.datasets.length} 个版本化数据集`],['训练实验',state.jobs.length,'组',`${state.jobs.filter(j=>j.status==='已完成').length} 组已完成 · 模拟结果`],['运行部署',state.deployments.length,'个','端边云节点 · 演示环境']].map(([l,v,u,f])=>`<div class="metric"><div class="metric-label">${l}<span>↗</span></div><div class="metric-value">${v}<small>${u}</small></div><div class="metric-foot">${f}</div></div>`).join('')}</div>`}
function jobsTable(){return `<div class="table-wrap"><table><thead><tr><th>实验名称</th><th>模型 / 数据</th><th>进度</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.jobs.map(j=>`<tr><td><strong>${esc(j.name)}</strong><small>${j.id}</small></td><td>${esc(j.model)}<br><small>${j.dataset}</small></td><td><div class="progress"><span style="width:${j.progress}%"></span></div><small>${j.progress}%</small></td><td>${badge(j.status,j.status==='已完成'?'':'blue')}</td><td><button onclick="jobDetail('${j.id}')">详情</button></td></tr>`).join('')}</tbody></table></div>`}
const views={
overview:()=>head('让每一次示教，成为新的能力。','从真实世界的数据出发，贯通机器人研发的每一步。',`<button onclick="location.hash='architecture'">查看架构 ↗</button><button class="primary" onclick="location.hash='capture'">＋ 开始采集</button>`)+`<section class="hero"><div class="hero-copy"><div class="eyebrow">PROJECT 01 / DEXTEROUS MANIPULATION</div><h2>连接身体与智能<br>构建灵巧操作闭环</h2><p>宇树 G1 × 因时灵巧手<br>统一管理设备、示教数据与模型实验。</p><button onclick="location.hash='devices'">进入设备工作台 →</button></div><div class="robot-stage"><div class="stage-label">DIGITAL ROBOT / CONCEPT VIEW</div>${robot()}</div></section>`+metrics()+`<div class="grid2"><section class="card"><div class="card-head"><h2>研发工作流</h2>${badge('端到端闭环')}</div><div class="flow">${[['capture','01','遥操作采集','TELEOP'],['datasets','02','数据治理','DATASET'],['models','03','模型选择','MODEL'],['training','04','训练评测','TRAIN'],['deploy','05','部署回流','DEPLOY']].map(([id,n,t,en],i)=>`${i?'<span class="arrow">→</span>':''}<a href="#${id}"><span class="step">${n}</span><b>${t}</b><small>${en}</small></a>`).join('')}</div><div class="note">当前建议：从桌面抓取示教开始，验证第一条完整研发链路。</div></section><section class="card"><div class="card-head"><h2>端边云资源</h2><a href="#architecture">拓扑详情 ↗</a></div>${[['端','Unitree G1','本地控制 · 设备状态','就绪'],['边','Edge-01','采集缓存 · 模型推理','就绪'],['云','Training-01','数据资产 · 训练资源','空闲']].map(([i,n,d,s])=>`<div class="node-row"><span class="node-icon">${i}</span><div><strong>${n}</strong><small>${d}</small></div>${badge(s)}</div>`).join('')}</section></div><section class="card"><div class="card-head"><h2>最近训练实验</h2><a href="#training">全部实验 →</a></div>${jobsTable()}</section>`,
devices:()=>head('设备调试','查看机器人状态，验证关节映射与灵巧手配置。',badge('模拟连接'))+`<div class="warning">本页控件仅更新界面中的模拟状态，不发送任何机器人指令。因时具体型号、自由度和通信参数将在接入时配置。</div><div class="grid-equal"><section class="card"><div class="card-head"><h2>G1 · 机器人概览</h2>${badge('SIM ONLINE')}</div><div class="preview">${robot()}</div><div class="node-row"><div><strong>宇树 G1 / 因时灵巧手</strong><small>设备档案 G1-LAB-001 · 具体硬件版本待配置</small></div></div><button onclick="toast('模拟自检完成：设备状态、控制通道、数据通道均正常')">运行模拟自检</button></section><section class="card"><div class="card-head"><h2>动作调试</h2>${badge('示意控制量','gray')}</div>${['左臂抬升','右臂抬升','左手闭合','右手闭合'].map((n,i)=>`<div class="joint"><label for="j${i}">${n}</label><input id="j${i}" type="range" min="0" max="100" value="${state.joints[i]}" oninput="state.joints[${i}]=+this.value;this.nextElementSibling.value=this.value+'%';save()"><output>${state.joints[i]}%</output></div>`).join('')}<p class="subtle">0–100% 为归一化演示量，不代表真实关节角度。</p><div class="actions" style="margin-top:25px"><button onclick="state.joints=[0,0,0,0];save();render();toast('模拟控制量已归零')">归零</button><button class="danger" onclick="capture.running=false;state.joints=[0,0,0,0];save();render();toast('模拟急停：已停止采集并将控制量归零')">模拟急停</button></div><div class="note" style="margin-top:30px">控制链路规划：控制权仲裁 → 指令检查 → 本地控制器 → 设备驱动。</div></section></div>`,
capture:()=>head('遥操作数采','把一次操作过程，转化为可复用的示教数据。',badge('TELEOP / SIMULATED','blue'))+`<div class="grid2"><section class="card"><div class="card-head"><h2>多模态采集预览</h2>${badge('示意画面','gray')}</div><div class="preview"><div class="preview-caption">HEAD CAMERA · SYNTHETIC SCENE</div><svg viewBox="0 0 600 260"><defs><pattern id="floor" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" stroke="#4d7778" fill="none" stroke-width=".5"/></pattern></defs><rect width="600" height="260" fill="url(#floor)"/><path d="M115 95h365l70 130H45Z" fill="#557477" stroke="#9cb0ae"/><path d="M45 225h505v12H45Z" fill="#29464c"/><rect x="235" y="112" width="47" height="46" rx="5" fill="#d2a56b"/><ellipse cx="353" cy="149" rx="24" ry="9" fill="#1b4349"/><path d="M332 110h42l-3 37q-18 8-36 0Z" fill="#b4dbcd"/><ellipse cx="353" cy="110" rx="21" ry="6" fill="#729d91"/><g fill="none" stroke="#b7c8c7" stroke-width="20" stroke-linecap="round"><path d="M156 260l20-67 41-20 M440 260l-20-67-28-23"/></g><g fill="none" stroke="#88c2a5" stroke-width="1"><rect x="222" y="96" width="74" height="76"/><rect x="320" y="96" width="63" height="76"/></g><text x="225" y="88" fill="#b9e5ce" font-size="10">OBJECT_01</text><text x="320" y="88" fill="#b9e5ce" font-size="10">OBJECT_02</text></svg><div class="preview-status">● RGB / 本体状态 / 手部状态 / 动作指令 · 模拟同步</div></div><div class="grid-equal" style="margin-top:18px"><div class="deploy-target"><strong>SONIC / TeleopIt</strong><p>遥操作与动作映射接口占位</p></div><div class="deploy-target"><strong>因时灵巧手</strong><p>位置与动作标签 · 触觉按硬件能力扩展</p></div></div></section><section class="card fields"><h2>创建采集片段</h2><label for="capture-task">任务类型</label><select id="capture-task" onchange="capture.task=this.value" ${capture.running?'disabled':''}>${['桌面抓取','双臂搬运','灵巧手控制'].map(t=>`<option ${t===capture.task?'selected':''}>${t}</option>`).join('')}</select><label>设备配置</label><input value="G1 + 因时灵巧手 / 演示配置" readonly><div class="timer" id="timer">${time(capture.seconds)}</div><div class="subtle" id="capture-status">${capture.running?'正在采集模拟片段':'等待开始 · 可暂停后保存'}</div><div class="actions"><button class="primary" onclick="toggleCapture()">${capture.running?'暂停采集':'开始 / 继续'}</button><button onclick="saveCapture()" ${capture.seconds<1?'disabled':''} id="save-capture">保存片段</button></div><p class="subtle">保存后自动生成一个包含 1 条示教片段的数据集，可用于模拟训练。</p></section></div>`,
datasets:()=>head('数据管理','统一管理示教数据、任务标注与版本。',`<button onclick="exportData()">导出数据清单 ↓</button><button class="primary" onclick="location.hash='capture'">＋ 采集数据</button>`)+`<section class="card"><div class="toolbar"><input id="data-search" placeholder="搜索数据集名称或任务…" aria-label="搜索数据集" oninput="filterData()"><select id="data-task" aria-label="筛选任务" onchange="filterData()"><option>全部任务</option><option>桌面抓取</option><option>双臂搬运</option><option>灵巧手控制</option></select><span class="count">${state.datasets.length} 个数据集 · 本地保存</span></div><div id="dataset-table">${datasetTable(state.datasets)}</div></section>`,
models:()=>head('模型中心','按能力层选择模型，绑定数据与设备配置。',badge('算法未接入','amber'))+`<div class="tabs">${['全部','操作策略','全身控制'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}</div><div class="model-grid">${[{name:'ACT',type:'操作策略',tag:'模仿学习',desc:'作为灵巧操作的首个基线，验证数据到动作的训练流程。',available:true},{name:'π₀ / VLA',type:'操作策略',tag:'视觉 · 语言 · 动作',desc:'展示预训练模型选择、任务数据绑定与微调配置。',available:true},{name:'SONIC',type:'全身控制',tag:'运动跟踪',desc:'复用现有全身控制能力，预留策略与部署配置接口。'},{name:'SuperMimic',type:'全身控制',tag:'适配规划',desc:'预留框架插件位置，接入前完成代码、权重与接口验证。'}].filter(m=>filter==='全部'||m.type===filter).map(m=>`<article class="model-card ${state.model===m.name?'selected':''}"><div class="card-head"><span class="model-mark">${m.name==='π₀ / VLA'?'π₀':m.name.slice(0,2)}</span>${badge(m.available?'模拟流程可用':'接口预留',m.available?'':'gray')}</div><h2>${m.name}</h2><div class="subtle">${m.type} / ${m.tag}</div><p>${m.desc}</p><div class="meta">目标设备 G1 + 因时灵巧手<br>权重与运行环境：尚未接入</div><button ${m.available?'':'disabled'} onclick="selectModel('${m.name}')">${state.model===m.name?'✓ 已选择':m.available?'选择模型':'待适配验证'}</button></article>`).join('')}</div><div class="warning" style="margin-top:22px">ACT 属于模仿学习策略；VLA 属于视觉语言动作策略；SONIC 与 SuperMimic 属于全身控制层，分别管理配置与接口。</div>`,
training:()=>head('训练实验','固定数据版本，记录每一次模型实验。',`<button class="primary" onclick="newTraining()">＋ 新建训练</button>`)+`<div class="warning">训练进度、损失与完成状态均由演示计时器生成，不代表真实 GPU 训练或模型效果。</div><section class="card"><div class="card-head"><h2>实验列表</h2>${badge('MOCK TRAINING','gray')}</div>${jobsTable()}</section>`,
deploy:()=>head('部署运行','将完成的实验发布到模拟节点，验证版本与回流流程。',badge('无真实推理','amber'))+`<div class="grid-equal"><section class="card fields"><h2>创建模拟部署</h2><label for="deploy-model">已完成的模型实验</label><select id="deploy-model">${state.jobs.filter(j=>j.status==='已完成').map(j=>`<option value="${j.id}">${esc(j.name)} · ${j.id}</option>`).join('')}</select><label for="deploy-node">运行节点</label><select id="deploy-node"><option>Edge-01 / 边缘推理节点</option><option>G1-端侧 / 本地执行节点</option></select><button class="primary" onclick="deployModel()">发布模拟版本</button><div class="note" style="margin-top:22px">规划：任务策略 → 动作适配 → 本地控制器。实时控制及异常处置保留在机器人端。</div></section><section class="card"><h2>运行中的版本</h2>${state.deployments.length?state.deployments.map(d=>`<div class="deploy-target"><div class="card-head"><strong>${esc(d.name)}</strong>${badge('模拟运行')}</div><p>${esc(d.node)} · ${d.id}</p><button onclick="feedback('${d.id}')">模拟失败片段回流</button> <button onclick="rollback('${d.id}')">撤回部署</button></div>`).join(''):'<div class="empty">暂无部署<br><small>选择已完成的实验，发布第一个版本。</small></div>'}</section></div>`,
architecture:()=>head('端—边—云整体架构','统一工作台连接数据、训练与机器人运行闭环。',`<a href="architecture.svg" download="具身工坊-整体架构.svg"><button>下载架构图 SVG ↓</button></a>`)+`<div class="arch-container"><img class="arch-img" src="architecture.svg" alt="端边云软件整体架构：统一工作台，云端训练与数据治理，边缘采集推理，机器人端控制以及数据回流"></div><div class="arch-details"><section class="card"><h3>端 · 机器人实时执行</h3><p>G1 与因时驱动、状态采集、控制权仲裁、指令约束、本地实时控制与异常处理。</p></section><section class="card"><h3>边 · 现场数据与推理</h3><p>遥操作接入、时间同步、片段记录、缓存与续传、策略推理，以及动作接口适配。</p></section><section class="card"><h3>云 · 资产与训练管理</h3><p>数据治理与版本、模型注册、训练调度、评测与发布。可部署于实验室私有服务器。</p></section></div><div class="warning" style="margin-top:20px">实线表示规划的业务数据流，虚线表示模型与配置下发。当前 Demo 仅实现浏览器交互及本地存储，图中后端服务、硬件驱动与算法均为后续建设内容。</div>`
};
function datasetTable(rows){return `<div class="table-wrap"><table><thead><tr><th>数据集</th><th>任务类型</th><th>片段数</th><th>模拟质量</th><th>版本</th><th>操作</th></tr></thead><tbody>${rows.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${d.id} · ${d.date}</small></td><td>${d.task}</td><td>${d.episodes}</td><td>${badge(d.quality+'%')}</td><td>${d.version}</td><td><button onclick="datasetDetail('${d.id}')">查看</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">没有符合条件的数据集</td></tr>'}</tbody></table></div>`}
function filterData(){const q=$('#data-search').value.trim().toLowerCase(),t=$('#data-task').value;$('#dataset-table').innerHTML=datasetTable(state.datasets.filter(d=>(d.name+d.task).toLowerCase().includes(q)&&(t==='全部任务'||d.task===t)))}
function modal(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function datasetDetail(id){const d=state.datasets.find(d=>d.id===id);modal(`<div class="page-head"><h2>${esc(d.name)}</h2><button onclick="closeModal()" aria-label="关闭">✕</button></div><p>${d.id} / ${d.version} / ${d.episodes} 条片段</p><div class="preview">${robot()}<div class="preview-caption">同步回放示意 · 非真实采集数据</div></div><label for="scrub" class="subtle">回放时间轴 <span id="scrub-time">0.0 s</span></label><input style="width:100%;accent-color:#087e68" id="scrub" type="range" min="0" max="100" value="0" oninput="$('#scrub-time').textContent=(this.value*.2).toFixed(1)+' s';$('#joint-reading').textContent=(Math.sin(this.value/10)*.5).toFixed(3)"><div class="note">模拟关节位置 <b id="joint-reading">0.000</b> rad · 图像 / 本体状态 / 手部控制量</div><p class="subtle">元数据规划：机器人配置、标定版本、观测时间、指令时间、任务标签及来源。</p><button class="primary" onclick="closeModal();location.hash='training';newTraining('${id}')">使用此数据集训练</button>`)}
function selectModel(name){state.model=name;save();render();toast('已选择 '+name+'，可前往训练实验创建任务')}
function newTraining(id){modal(`<div class="page-head"><h2>新建模拟训练</h2><button onclick="closeModal()" aria-label="关闭">✕</button></div><form class="fields" onsubmit="event.preventDefault();startTraining()"><label for="train-name">实验名称</label><input id="train-name" required maxlength="60" value="灵巧操作实验 ${state.jobs.length+1}"><label for="train-data">数据集版本</label><select id="train-data">${state.datasets.map(d=>`<option value="${d.id}" ${d.id===id?'selected':''}>${esc(d.name)} · ${d.version}</option>`).join('')}</select><label for="train-model">算法模型</label><select id="train-model">${['ACT','π₀ / VLA'].map(m=>`<option ${state.model===m?'selected':''}>${m}</option>`).join('')}</select><label for="train-mode">训练方式</label><select id="train-mode"><option>任务数据微调（模拟）</option><option>基线训练（模拟）</option></select><p class="subtle">提交后约 25 秒完成演示进度；不会加载权重、占用 GPU 或生成真实模型。</p><button class="primary" type="submit">提交模拟训练</button></form>`)}
function startTraining(){let name=$('#train-name').value.trim();if(!name){toast('请输入实验名称');return}state.jobs.unshift({id:'TR-'+Date.now().toString().slice(-6),name,model:$('#train-model').value,dataset:$('#train-data').value,mode:$('#train-mode').value,progress:0,status:'训练中',loss:.8});save();closeModal();location.hash='training';render();toast('模拟训练已启动')}
function jobDetail(id){const j=state.jobs.find(j=>j.id===id);modal(`<div class="page-head"><h2>实验详情</h2><button onclick="closeModal()" aria-label="关闭">✕</button></div><p>${esc(j.name)} · ${j.model} · ${j.dataset}</p><div class="warning">以下为生成的示意曲线与日志，不是算法训练结果。</div><svg class="spark" viewBox="0 0 520 130"><path d="M30 15V110H500" fill="none" stroke="#d7e3dc"/><path d="M30 25L65 48 100 44 135 70 170 65 210 84 260 90 310 96 350 97 400 102 460 105" fill="none" stroke="#27906e" stroke-width="2"/><text x="360" y="30" font-size="11" fill="#7b8e87">LOSS / SIMULATED</text></svg><div class="log">[MOCK] 数据版本：${j.dataset}\n[MOCK] 模型配置：${j.model}\n[MOCK] 训练进度：${j.progress}%\n[MOCK] 当前状态：${j.status}</div><button style="margin-top:15px" onclick="closeModal();location.hash='deploy'" ${j.status==='已完成'?'':'disabled'}>前往部署</button>`)}
const time=s=>Math.floor(s/60).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0');
function toggleCapture(){capture.running=!capture.running;render()}
function addDataset(name,task,episodes=1){const d={id:'DS-'+Date.now().toString().slice(-8),name,task,episodes,quality:97.8,date:new Date().toLocaleDateString('sv-SE'),version:'v1.0'};state.datasets.unshift(d);save();return d}
function saveCapture(){if(capture.seconds<1)return;addDataset(capture.task+' · 新采集 '+time(capture.seconds),capture.task);capture.running=false;capture.seconds=0;location.hash='datasets';render();toast('模拟片段已保存到数据管理')}
function deployModel(){const id=$('#deploy-model').value,j=state.jobs.find(j=>j.id===id);if(!j)return toast('请先完成一个训练实验');const node=$('#deploy-node').value;if(state.deployments.some(d=>d.node===node))return toast('该节点已有运行版本，请先撤回当前部署');state.deployments.unshift({id:'DEP-'+Date.now().toString().slice(-6),name:j.name,node,job:id});save();render();toast('模拟版本已发布')}
function rollback(id){state.deployments=state.deployments.filter(d=>d.id!==id);save();render();toast('模拟部署已撤回，节点恢复空闲')}
function feedback(id){addDataset('部署回流 · '+id,'桌面抓取');toast('已生成模拟失败片段，可在数据管理中查看')}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){download('具身工坊-模拟数据清单.json',JSON.stringify({simulated:true,datasets:state.datasets},null,2),'application/json');toast('模拟数据清单已导出')}
function resetDemo(){modal(`<h2>重置演示数据</h2><p>将清除本浏览器新建的数据集、实验和部署，恢复初始演示内容。</p><div class="actions" style="margin-top:20px"><button onclick="closeModal()">取消</button><button class="danger" onclick="state=initial();capture={running:false,seconds:0,task:'桌面抓取'};save();closeModal();render();toast('演示数据已重置')">确认重置</button></div>`)}
function render(){page=location.hash.slice(1)||'overview';if(!views[page])page='overview';$('#app').innerHTML=views[page]();$('#breadcrumb').innerHTML='工作空间 / <b>'+pages.find(p=>p[0]===page)[1]+'</b>';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page))}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
setInterval(()=>{if(capture.running){capture.seconds++;if(page==='capture'){$('#timer').textContent=time(capture.seconds);$('#save-capture').disabled=false}}let changed=false;state.jobs.forEach(j=>{if(j.status==='训练中'){j.progress=Math.min(100,j.progress+4);j.loss=+(0.8*(1-j.progress/100)+.024).toFixed(3);if(j.progress===100){j.status='已完成';toast(j.name+'：模拟训练完成')}changed=true}});if(changed){save();if(page==='training'||page==='overview')render()}},1000);
